const MANUAL_TIMEZONE_KEY = 'athlete_manual_timezone';
const MOBILE_VIEW_MODE_KEY = 'mobile_view_mode';
const FALLBACK_TIMEZONE = 'America/Los_Angeles';
const FETCH_TIMEOUT_MS = 15000;

export function getDeviceTimezone(): string | null {
  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
    return tz && String(tz).trim() ? String(tz).trim() : null;
  } catch {
    return null;
  }
}

export async function getManualTimezonePreference(): Promise<string | null> {
  const tz = await SecureStore.getItemAsync(MANUAL_TIMEZONE_KEY);
  return tz && String(tz).trim() ? String(tz).trim() : null;
}

export async function setManualTimezonePreference(timezone: string | null) {
  const tz = timezone && String(timezone).trim();
  if (tz) {
    await SecureStore.setItemAsync(MANUAL_TIMEZONE_KEY, tz);
  } else {
    await SecureStore.deleteItemAsync(MANUAL_TIMEZONE_KEY);
  }
}

export async function getResolvedTimezone(): Promise<string> {
  return (await getManualTimezonePreference()) || getDeviceTimezone() || FALLBACK_TIMEZONE;
}

export type FetchJsonResult<T> = {
  ok: boolean;
  status: number;
  json: T | null;
  raw: string;
  failure?: {
    kind: 'http' | 'malformed-response';
    method: string;
    path: string;
    requestId: string;
    elapsedMs: number;
  } | null;
};

type ApiFetchInit = RequestInit & {
  auth?: boolean;
  evidenceSubject?: string;
  timeoutMs?: number;
  requestImportance?: ApiRequestImportance;
};

export type AccountStatePayload = {
  ok?: boolean;
  error?: string;
  email_verified?: boolean;
  account_state?: string | null;
  next_url?: string | null;
  next_route?: string | null;
  can_access_product?: boolean;
  billing_required?: boolean;
  verification_required?: boolean;
  link_coach_required?: boolean;
  workspace_mode?: 'team' | 'individual' | string | null;
  available_mobile_modes?: string[] | null;
  mobile_mode?: 'athlete' | 'coach' | 'individual' | string | null;
  can_access_internal_self_coach_mobile_mode?: boolean;
  role?: string | null;
  athlete_id?: number | null;
  preferred_units?: 'kg' | 'lb' | 'lbs' | null;
  coach_id?: number | null;
  reason?: string | null;
  account_state_detail?: any;
  billing_url?: string | null;
  verification_url?: string | null;
  link_coach_url?: string | null;
  dev_onboarding_simulation_enabled?: boolean;
  user?: Record<string, any>;
};

type AccountStateBlockListener = (payload: AccountStatePayload, context: { path: string; status: number }) => void;
const accountStateBlockListeners = new Set<AccountStateBlockListener>();

export function isAccountStateBlockedPayload(payload: any): payload is AccountStatePayload {
  if (!payload || typeof payload !== 'object') return false;
  const state = typeof payload.account_state === 'string' ? payload.account_state : '';
  return (
    payload.can_access_product === false ||
    state === 'EMAIL_VERIFICATION_REQUIRED' ||
    state === 'ACTIVATION_REQUIRED' ||
    state === 'LINK_COACH_REQUIRED' ||
    payload.billing_required === true ||
    payload.verification_required === true ||
    payload.link_coach_required === true
  );
}

export function subscribeAccountStateBlocks(listener: AccountStateBlockListener): () => void {
  accountStateBlockListeners.add(listener);
  return () => {
    accountStateBlockListeners.delete(listener);
  };
}

function notifyAccountStateBlock(payload: AccountStatePayload, context: { path: string; status: number }) {
  for (const listener of Array.from(accountStateBlockListeners)) {
    try {
      listener(payload, context);
    } catch (err) {
      console.warn('Account-state block listener failed', err);
    }
  }
}

let requestSequence = 0;

function createRequestId() {
  requestSequence = (requestSequence + 1) % 1_000_000;
  return `mobile-${Date.now().toString(36)}-${requestSequence.toString(36)}`;
}

function diagnosticPath(path: string) {
  try {
    const parsed = new URL(path, API_BASE);
    return parsed.pathname;
  } catch {
    return path.split('?')[0] || path;
  }
}

function mobileAppVersionHeaders(): Record<string, string> {
  const expoConfig: any = Constants.expoConfig || {};
  const appVersion =
    (Constants as any).nativeApplicationVersion ||
    expoConfig.version ||
    '';
  const buildVersion =
    (Constants as any).nativeBuildVersion ||
    expoConfig.ios?.buildNumber ||
    expoConfig.android?.versionCode ||
    '';
  const headers: Record<string, string> = {
    'X-Strength-Ledger-Platform': Platform.OS,
    'X-Strength-Ledger-Volume-Landmarks': '2',
    'X-Strength-Ledger-Current-Movement-Contract': '1',
  };
  if (appVersion) headers['X-Strength-Ledger-App-Version'] = String(appVersion);
  if (buildVersion) headers['X-Strength-Ledger-Build'] = String(buildVersion);
  return headers;
}

export async function fetchJson<T = any>(
  path: string,
  init: ApiFetchInit = {}
): Promise<FetchJsonResult<T>> {
  // If callers pass a plain object as `body`, React Native fetch will NOT serialize it.
  // Normalize to a JSON string body when appropriate.
  const method = String(init.method || 'GET').toUpperCase();
  const idealResult =
    typeof __DEV__ !== 'undefined' && __DEV__
      ? resolveProductionIdealRequest<T>(path, init)
      : null;
  if (idealResult) return idealResult;

  const url = path.startsWith('http') ? path : `${API_BASE}${path}`;
  const {
    auth: authMode,
    evidenceSubject,
    timeoutMs = FETCH_TIMEOUT_MS,
    requestImportance = method === 'GET' ? 'foreground-read' : 'critical-mutation',
    ...fetchInit
  } = init;
  const requestId = createRequestId();
  const requestPath = diagnosticPath(path);
  const requestStartedAt = Date.now();
  const rawBody: any = (init as any).body;
  const bodyIsPresent = rawBody !== undefined && rawBody !== null;

  const isFormData = typeof FormData !== 'undefined' && rawBody instanceof FormData;
  const isBlob = typeof Blob !== 'undefined' && rawBody instanceof Blob;
  const isArrayBuffer = typeof ArrayBuffer !== 'undefined' && rawBody instanceof ArrayBuffer;

  const shouldJsonEncodeBody =
    bodyIsPresent &&
    method !== 'GET' &&
    method !== 'HEAD' &&
    typeof rawBody !== 'string' &&
    !isFormData &&
    !isBlob &&
    !isArrayBuffer;

  const normalizedBody: any = shouldJsonEncodeBody ? JSON.stringify(rawBody) : rawBody;

  // ---- Mobile auth: attach Bearer token automatically (if present) ----
  // AuthContext stores the token in SecureStore; support a few key names for safety.
  const token =
    (await SecureStore.getItemAsync('auth_token')) ||
    (await SecureStore.getItemAsync('token')) ||
    (await SecureStore.getItemAsync('pl_token')) ||
    (await SecureStore.getItemAsync('powerlift_token'));

  const normalizeHeaders = (h: HeadersInit | undefined): Record<string, string> => {
    if (!h) return {};
    // Headers instance
    if (typeof (h as any).forEach === 'function') {
      const out: Record<string, string> = {};
      (h as any).forEach((value: string, key: string) => {
        out[key] = value;
      });
      return out;
    }
    // Array of tuples
    if (Array.isArray(h)) {
      const out: Record<string, string> = {};
      for (const [k, v] of h) out[String(k)] = String(v);
      return out;
    }
    // Plain object
    return h as Record<string, string>;
  };

  const callerHeaders = normalizeHeaders(init.headers as any);

  const defaultHeaders: Record<string, string> = {
    Accept: 'application/json',
    ...mobileAppVersionHeaders(),
  };

  // Only set Content-Type when sending a JSON body (and caller didn't set it)
  const hasBody = normalizedBody !== undefined && normalizedBody !== null;
  const hasContentType =
    Object.keys(callerHeaders).some((k) => k.toLowerCase() === 'content-type');

  if (hasBody && !hasContentType && !isFormData) {
    // If we normalized to JSON, or caller provided a string body but didn't set CT,
    // default to JSON because all our endpoints are JSON.
    defaultHeaders['Content-Type'] = 'application/json';
  }

  const mergedHeaders: Record<string, string> = {
    ...defaultHeaders,
    'X-Strength-Ledger-Request-ID': requestId,
    ...callerHeaders,
  };

  const hasTimezoneHeader = Object.keys(mergedHeaders).some(
    (k) => k.toLowerCase() === 'x-timezone' || k.toLowerCase() === 'x-time-zone'
  );
  if (!hasTimezoneHeader) {
    mergedHeaders['X-Timezone'] = await getResolvedTimezone();
  }
  const hasMobileModeHeader = Object.keys(mergedHeaders).some((k) => k.toLowerCase() === 'x-strength-ledger-mobile-mode');
  if (!hasMobileModeHeader) {
    try {
      const mobileMode = String((await AsyncStorage.getItem(MOBILE_VIEW_MODE_KEY)) || '').trim().toLowerCase();
      if (['athlete', 'coach', 'individual'].includes(mobileMode)) {
        mergedHeaders['X-Strength-Ledger-Mobile-Mode'] = mobileMode;
      }
    } catch {
      // Mobile mode is only a view hint; requests must continue without it.
    }
  }

  // Only set Authorization if caller didn't explicitly set it (any case)
  const wantsAuth = authMode !== false;
  const hasAuth = Object.keys(mergedHeaders).some((k) => k.toLowerCase() === 'authorization');
  if (wantsAuth && token && !hasAuth) {
    mergedHeaders.Authorization = `Bearer ${token}`;
  }

  if (__DEV__) {
    const authPresent = Object.keys(mergedHeaders).some((k) => k.toLowerCase() === 'authorization');
    console.log(
      'fetchJson',
      method,
      url,
      'auth?',
      authPresent,
      'authMode?',
      wantsAuth ? 'auto' : 'off',
      'hasBody?',
      hasBody,
      'tz?',
      mergedHeaders['X-Timezone'] || mergedHeaders['X-Time-Zone'] || 'none'
    );
  }

  const evidenceRead = method === 'GET' && wantsAuth && Boolean(token) && isEvidenceRead(path);
  const performRequest = async (): Promise<FetchJsonResult<T>> => {
    const controller = new AbortController();
    const callerSignal = evidenceRead ? undefined : fetchInit.signal;
    let didTimeout = false;
    let timeoutId: ReturnType<typeof setTimeout> | null = null;
    let removeCallerAbortListener: (() => void) | null = null;

    if (callerSignal) {
      if (callerSignal.aborted) {
        controller.abort();
      } else {
        const abortFromCaller = () => controller.abort();
        callerSignal.addEventListener('abort', abortFromCaller);
        removeCallerAbortListener = () => callerSignal.removeEventListener('abort', abortFromCaller);
      }
    }

    if (timeoutMs > 0) {
      timeoutId = setTimeout(() => {
        didTimeout = true;
        controller.abort();
      }, timeoutMs);
    }

    let res: Response;
    try {
      res = await fetch(url, {
        ...fetchInit,
        method,
        headers: mergedHeaders,
        body: normalizedBody as any,
        credentials: (init.credentials as any) ?? 'include',
        signal: controller.signal,
      });
    } catch (err: any) {
      const elapsedMs = Date.now() - requestStartedAt;
      if (didTimeout) {
        const timeoutError = new ApiRequestError({
          kind: 'timeout',
          message: `Request timed out after ${Math.round(timeoutMs / 1000)} seconds. Please try again.`,
          method,
          path: requestPath,
          timeoutMs,
          importance: requestImportance,
          requestId,
          elapsedMs,
        });
        console.warn('[ApiRequest]', {
          kind: timeoutError.kind,
          method,
          path: requestPath,
          importance: requestImportance,
          elapsed_ms: elapsedMs,
          request_id: requestId,
        });
        throw timeoutError;
      }
      const cancelled = Boolean(callerSignal?.aborted || controller.signal.aborted || err?.name === 'AbortError');
      const requestError = new ApiRequestError({
        kind: cancelled ? 'cancelled' : 'network',
        message: cancelled ? 'Request cancelled.' : 'The request could not reach Strength Ledger.',
        method,
        path: requestPath,
        importance: requestImportance,
        requestId,
        elapsedMs,
      });
      if (!cancelled) {
        console.warn('[ApiRequest]', {
          kind: requestError.kind,
          method,
          path: requestPath,
          importance: requestImportance,
          elapsed_ms: elapsedMs,
          request_id: requestId,
        });
      }
      throw requestError;
    } finally {
      if (timeoutId) clearTimeout(timeoutId);
      if (removeCallerAbortListener) removeCallerAbortListener();
    }

    let raw = '';
    try {
      raw = await res.text();
    } catch {
      raw = '';
    }

    const trimmed = raw.trim();
    let json: T | null = null;
    if (trimmed.length > 0) {
      try {
        json = JSON.parse(trimmed) as T;
        if (res.ok && /\/workouts\/mobile\//.test(url)) json = normalizeSessionMovementResponse(json);
        if (res.ok && method === 'GET') json = filterRetiredMovementLibraryResponse(path, json);
      } catch {
        console.log('fetchJson parse failed:', res.status, url, trimmed.slice(0, 300));
        json = null;
      }
    }

    if (!res.ok && isAccountStateBlockedPayload(json)) {
      notifyAccountStateBlock(json, { path, status: res.status });
    }

    if (__DEV__ && !res.ok) {
      const endpoint = (() => {
        try {
          const parsed = new URL(url);
          return `${parsed.pathname}${parsed.search}`;
        } catch {
          return path;
        }
      })();
      console.warn('fetchJson response error', method, endpoint, 'status', res.status);
    }

    return {
      ok: res.ok,
      status: res.status,
      json,
      raw,
      failure: !res.ok
        ? {
            kind: 'http',
            method,
            path: requestPath,
            requestId,
            elapsedMs: Date.now() - requestStartedAt,
          }
        : trimmed.length > 0 && json == null
          ? {
              kind: 'malformed-response',
              method,
              path: requestPath,
              requestId,
              elapsedMs: Date.now() - requestStartedAt,
            }
          : null,
    };
  };
  // This endpoint computes a suggestion and performs no write. Keep its
  // transport from invalidating evidence during every prescription keystroke.
  const programmingSuggestionRead = method === 'POST' && requestPath === '/workouts/mobile/suggest_range';
  if (programmingSuggestionRead) return performRequest();
  if (method !== 'GET' && method !== 'HEAD') {
    evidenceReadCache.invalidate(false);
    try { return await performRequest(); } finally { invalidateEvidenceReads({ path: requestPath }); }
  }
  const header = (...names: string[]) => String(Object.entries(mergedHeaders).find(([key]) => names.includes(key.toLowerCase()))?.[1] || '');
  const response = evidenceRead
    ? await evidenceReadCache.read(
      header('authorization') || token!,
      `${url}|${evidenceSubject || ''}|${header('x-strength-ledger-mobile-mode')}|${header('x-timezone', 'x-time-zone')}`,
      performRequest,
    ) : await performRequest();
  if ([401, 403, 404].includes(response.status)) evidenceReadCache.invalidate(false);
  if ([401, 403].includes(response.status)) sessionExposureCache.deny();
  if (response.ok && /^\/workouts\/mobile\/\d+(?:\?|$)/.test(requestPath)) sessionExposureCache.authorize();
  if (fetchInit.signal?.aborted) throw new ApiRequestError({
    kind: 'cancelled', message: 'Request cancelled.', method, path: requestPath,
    importance: requestImportance, requestId, elapsedMs: Date.now() - requestStartedAt,
  });
  return response;

}

